    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"الحدود متساوية","math":"الحدود 6 متساوية، و جمع 6 حدود متساوية هو ضربها في 6"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">5<sup>5</sup> + 5<sup>5</sup> + 5<sup>5</sup> + 5<sup>5</sup> + 5<sup>5</sup> + 5<sup>5</sup> = 6 × 5<sup>5</sup></span>"},{"quoi":"نُظهر القاسم 50","math":"<span dir=\"ltr\" class=\"expr\">6 × 5<sup>5</sup> = 50 × (3 × 5<sup>3</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">50 × 3 × 5<sup>3</sup></span> و منه يقبل القسمة على 50"}],
