    correction: [{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 4 + 20/(n + 5)</span>"},{"quoi":"الشرط","math":"4 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">20/(n + 5)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 5</span> يجب أن يكون قاسما للعدد 20"},{"quoi":"قواسم 20","math":"قواسم 20 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 4 ؛ 5 ؛ 10 ؛ 20</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 5 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -25 ؛ -15 ؛ -10 ؛ -9 ؛ -7 ؛ -6 ؛ -4 ؛ -3 ؛ -1 ؛ 0 ؛ 5 ؛ 15</span>"}],
